class Solution {
    public int shareCandies(int[] candies, int k) {
        Map<Integer, Integer> cnt = new HashMap<>();
        for (int c : candies) cnt.merge(c, 1, Integer::sum);
        if (k == 0) return cnt.size();
        int best = 0;
        for (int i = 0; i < candies.length; i++) {
            if (cnt.merge(candies[i], -1, Integer::sum) == 0) cnt.remove(candies[i]);
            if (i >= k) cnt.merge(candies[i - k], 1, Integer::sum);
            if (i >= k - 1) best = Math.max(best, cnt.size());
        }
        return best;
    }
}
